#!/usr/bin/env node
// Writes the Logic Probe sketch and its compiled HEX into a TypeScript module.
import { readFileSync, writeFileSync } from 'node:fs';

const [sketch, hex, out] = process.argv.slice(2);
const body = `/**
 * Benchtop's Logic Probe: a sketch that turns an Arduino Uno or Nano into a
 * six-channel logic analyser (firmware/avr/logic-probe), and the same
 * compiled for the Uno with avr-gcc and Benchtop's small Arduino-style core.
 * Generated by firmware/avr/build-probe.sh; do not edit by hand.
 */
export const LOGIC_PROBE_SKETCH = ${JSON.stringify(readFileSync(sketch, 'utf8'))};

export const LOGIC_PROBE_HEX = ${JSON.stringify(readFileSync(hex, 'utf8'))};
`;
writeFileSync(out, body);
console.log(`Wrote ${out}`);
